// Express 예시
app.get('/', (req, res) => {
  const nonce = crypto.randomUUID()  // 요청마다 새 nonce 생성
  res.setHeader('Content-Security-Policy', `script-src 'nonce-${nonce}'`)
  res.send(`<script nonce="${nonce}">안전한 코드</script>`)
})

